export const faqTopics = [
  { id: "faq-what-is-ndc", category: "Finance", question: "What is a Non-Drawal Certificate (NDC)?", question_te: "Non-Drawal Certificate (NDC) అంటే ఏమిటి?", answer: "NDC certifies that no pay, allowance, or recovery is pending with the DDO/treasury. It is required before transfer, retirement, or final settlement.", answer_te: "DDO/treasury వద్ద pending pay, allowance లేదా recovery లేదని NDC certify చేస్తుంది. Transfer, retirement లేదా final settlement కు ముందు అవసరం." },
  { id: "faq-cfms-login", category: "Treasury", question: "How do I access CFMS for pay bills?", question_te: "Pay bills కు CFMS ఎలా access చేయాలి?", answer: "Use your DDO login at cfms.ap.gov.in. Bill preparation requires valid employee master data and prior month bill passed status.", answer_te: "cfms.ap.gov.in లో DDO login ఉపయోగించండి. Bill preparation కు valid employee master మరియు previous bill passed status అవసరం." },
  { id: "faq-probation-period", category: "Establishment", question: "How long is probation for direct recruits?", question_te: "Direct recruits కు probation ఎంత కాలం?", answer: "Generally two years from date of joining under FR 9, unless a different period is specified in the appointment order. Verify your category rules.", answer_te: "సాధారణంగా joining date నుండి రెండు సంవత్సరాలు FR 9 ప్రకారం. Appointment order లో వేరే period ఉంటే verify చేయండి." },
  { id: "faq-el-balance", category: "Leave", question: "How is earned leave calculated?", question_te: "Earned leave ఎలా calculate అవుతుంది?", answer: "EL is credited as per AP Leave Rules — typically 15 days per year for most categories, subject to maximum accumulation limits. Check your leave account register.", answer_te: "AP Leave Rules ప్రకారం EL credit — చాలా categories కు సంవత్సరానికి 15 days. Maximum limit check చేయండి." },
  { id: "faq-apgli-loan-max", category: "APGLI", question: "What is the maximum APGLI loan?", question_te: "APGLI loan maximum ఎంత?", answer: "Loan amount depends on sum assured, premium paid, and current APGLI rules. Verify on apgli.ap.gov.in and with your APGLI office.", answer_te: "Loan amount sum assured, premium paid మరియు current rules పై depend. apgli.ap.gov.in verify చేయండి." },
  { id: "faq-gpf-advance-purpose", category: "GPF", question: "For what purposes can GPF advance be taken?", question_te: "GPF advance ఏ purposes కు?", answer: "Common purposes include marriage, education, house construction, and medical needs — as per GPF rules. Purpose must be documented in sanction proceedings.", answer_te: "Marriage, education, house, medical — GPF rules ప్రకారం. Sanction proceedings లో purpose document చేయాలి." },
  { id: "faq-lpc-when", category: "Establishment", question: "When is LPC required?", question_te: "LPC ఎప్పుడు అవసరం?", answer: "Last Pay Certificate is prepared when an employee is relieved for transfer, retirement, or death — certifying pay and recoveries up to last working day.", answer_te: "Employee transfer, retirement లేదా death సమయంలో LPC — last working day వరకు pay/recoveries certify." },
  { id: "faq-fr22-options", category: "Finance", question: "What are FR 22 options on promotion?", question_te: "Promotion పై FR 22 options ఏమిటి?", answer: "Employee may opt for pay fixation from date of promotion (FR 22(b)) or from date of next increment (FR 22(a)(i)). Option letter must be obtained in writing.", answer_te: "Promotion date (FR 22(b)) లేదా next increment date (FR 22(a)(i)) — written option letter అవసరం." },
  { id: "faq-maternity-days", category: "Leave", question: "How many days of maternity leave?", question_te: "Maternity leave ఎన్ని days?", answer: "Eligible women employees may avail up to 180 days maternity leave as per current AP rules. Verify latest GO on GOIR.", answer_te: "Eligible women employees కు 180 days వరకు — latest GO GOIR లో verify." },
  { id: "faq-da-arrears", category: "Finance", question: "When are DA arrears paid?", question_te: "DA arrears ఎప్పుడు pay?", answer: "After DA enhancement GO, DDO prepares supplementary/arrears bill in CFMS for eligible period. Payment follows treasury pass.", answer_te: "DA GO తర్వాత CFMS లో supplementary bill — treasury pass తర్వాత payment." },
  { id: "faq-rbps-nidhi", category: "Finance", question: "What is RBPS on NIDHI?", question_te: "NIDHI RBPS అంటే?", answer: "Retirement Benefits Processing System on NIDHI platform processes pension and retirement dues digitally as per DTA instructions.", answer_te: "NIDHI platform లో retirement benefits digital processing — DTA instructions ప్రకారం." },
  { id: "faq-bcr-due-date", category: "Establishment", question: "When should BCR be submitted?", question_te: "BCR ఎప్పుడు submit?", answer: "Broad Sheet is usually submitted monthly to Head of Office by the date fixed in office instructions — often before pay bill preparation.", answer_te: "Broad Sheet monthly HO కు — pay bill కు ముందు office instructions ప్రకారం." },
  { id: "faq-charge-memo-time", category: "Conduct", question: "How long to reply to charge memo?", question_te: "Charge memo reply time?", answer: "Employee is given prescribed time (often 15 days) to submit written reply. Exact period is stated in the charge memo.", answer_te: "Charge memo లో mentioned period (often 15 days) లో written reply." },
  { id: "faq-festival-advance-recovery", category: "Finance", question: "How is festival advance recovered?", question_te: "Festival advance recovery?", answer: "Recovery is made in equal installments from salary over the period specified in sanction order, typically 10 months.", answer_te: "Sanction order లో mentioned installments — usually 10 months." },
  { id: "faq-hpl-medical", category: "Leave", question: "Is medical certificate mandatory for HPL?", question_te: "HPL కు medical certificate?", answer: "Yes, for medical grounds HPL requires certificate from authorized medical officer as per leave rules.", answer_te: "Medical grounds HPL కు authorized medical officer certificate అవసరం." },
  { id: "faq-increment-stoppage", category: "Finance", question: "Can increment be stopped?", question_te: "Increment stop చేయవచ్చా?", answer: "Yes, as penalty under disciplinary proceedings increment may be withheld for specified period. Check penalty order.", answer_te: "Disciplinary penalty లో increment withhold — penalty order check." },
  { id: "faq-macp-eligibility", category: "Finance", question: "Who is eligible for MACP?", question_te: "MACP eligibility?", answer: "Employees who completed required years in grade without promotion may get MACP — verify vigilance clearance and current MACP GO.", answer_te: "Grade లో required years without promotion — vigilance clearance verify." },
  { id: "faq-ehs-referral", category: "Health", question: "Is EHS referral mandatory?", question_te: "EHS referral mandatory?", answer: "For empanelled hospital treatment under EHS, referral from authorized institution is generally required unless emergency norms apply.", answer_te: "EHS empanelled hospital కు referral usually mandatory — emergency rules check." },
  { id: "faq-pension-qualifying-service", category: "Finance", question: "What is minimum qualifying service for pension?", question_te: "Pension minimum service?", answer: "Generally 10 years qualifying service for pension — verify current pension rules and category.", answer_te: "Generally 10 years qualifying service — category rules verify." },
  { id: "faq-treasury-rejection", category: "Treasury", question: "Why is my CFMS bill rejected?", question_te: "CFMS bill reject ఎందుక?", answer: "Common reasons: employee master mismatch, leave not updated, missing proceedings, wrong DDO code, or validation errors. Read CFMS remarks.", answer_te: "Master mismatch, leave error, missing proceedings — CFMS remarks read." },
  { id: "faq-attestation", category: "Establishment", question: "Can office attest private certificates?", question_te: "Private certificates attest?", answer: "Head of Office may attest copies for official purposes when employee identity is verified — maintain attestation register.", answer_te: "Official purposes కు identity verify చేసి attest — register maintain." },
  { id: "faq-noc-vigilance", category: "Establishment", question: "Is vigilance clearance needed for NOC?", question_te: "NOC కు vigilance?", answer: "Many offices require no vigilance objection and loan clearance before issuing passport NOC.", answer_te: "Passport NOC కు vigilance objection లేకుండా ఉండాలి." },
  { id: "faq-el-encashment-max", category: "Leave", question: "Maximum EL encashment at retirement?", question_te: "Retirement EL encashment max?", answer: "Encashment limited by rules — often up to 300 days total subject to balance available. Verify current leave rules.", answer_te: "Rules ప్రకారం limit — often 300 days subject to balance." },
  { id: "faq-supplementary-bill", category: "Treasury", question: "When to draw supplementary bill?", question_te: "Supplementary bill ఎప్పుడు?", answer: "When pay element was omitted or wrongly paid in regular bill — with supporting proceedings and GO reference.", answer_te: "Regular bill లో omission/wrong pay — proceedings తో." },
  { id: "faq-aas-12-years", category: "Finance", question: "What happens after 12 years in same grade?", question_te: "12 years same grade?", answer: "Employee may become eligible for AAS stagnation increment — verify years, vigilance, and current AAS GO.", answer_te: "AAS stagnation increment eligibility — years మరియు GO verify." },
  { id: "faq-ddo-it-deadline", category: "Finance", question: "When is DDO IT declaration due?", question_te: "DDO IT declaration deadline?", answer: "Usually before February pay bill processing each financial year — verify Finance Department circular for exact date.", answer_te: "February pay bill కు ముందు — Finance circular date verify." },
  { id: "faq-service-book", category: "Establishment", question: "Difference between SR and service book?", question_te: "SR vs service book?", answer: "Service Register is institution record of orders; service book is employee's consolidated service record maintained per rules.", answer_te: "SR institution orders record; service book employee consolidated record." },
  { id: "faq-relieving-without-lpc", category: "Establishment", question: "Can employee join without LPC?", question_te: "LPC లేకుండా join?", answer: "Joining may be provisional; new office should obtain LPC from previous DDO. Do not regularize pay without LPC.", answer_te: "Provisional joining possible; LPC previous DDO నుండి — LPC లేక pay regularize చేయవద్దు." },
  { id: "faq-officemitra-official", category: "General", question: "Is OfficeMitra an official government site?", question_te: "OfficeMitra official site?", answer: "No. OfficeMitra is an independent knowledge platform. Always verify orders on GOIR and official department portals.", answer_te: "లేదు. OfficeMitra independent platform — GOIR లో official orders verify చేయండి." },
  { id: "faq-contact-expert", category: "General", question: "How do I get personalized help?", question_te: "Personalized help?", answer: "Use Expert Assistance on OfficeMitra for case-specific guidance from administrative practitioners.", answer_te: "Expert Assistance form ఉపయోగించండి case-specific guidance కు." },
];

